  1	/**
  2	 * Feature Notification Watcher — detects feature-level lifecycle events and
  3	 * routes them to the NotificationPort.
  4	 *
  5	 * Called once per poll cycle (after syncWorkspaces). Tracks per-process state
  6	 * so it can distinguish the "first active poll" (feature_start) from a
  7	 * "status change" (feature_summary_changed).
  8	 *
  9	 * Guarantees:
 10	 * - Calls postFeatureMessage('feature_start', ...) exactly once per
 11	 *   process run per feature the first time it is seen in an active state.
 12	 *   ensureFeatureThread is idempotent via Redis so restart re-entry is safe.
 13	 * - Calls postFeatureMessage('feature_summary_changed', ...) only when
 14	 *   feature_status or next_action changes after the initial start.
 15	 * - Never calls the port on a routine poll with no change.
 16	 * - Never calls postFeatureMessage for task-only transitions (it only reads
 17	 *   feature-level fields from status.yaml).
 18	 * - Skips terminal features (done, cancelled).
 19	 */
 20	
 21	import { existsSync, readdirSync, readFileSync } from "node:fs";
 22	import { execSync } from "node:child_process";
 23	import { join } from "node:path";
 24	import { parse as parseYaml } from "yaml";
 25	import type { NotificationPort } from "../notifications/notification.port.js";
 26	import type { FeatureContext } from "../notifications/notification.types.js";
 27	import { featuresRoot, featureBranchName, statusYamlRelPath, TASKS_DIR } from "../paths.js";
 28	import { buildGitEnv } from "../git-env.js";
 29	
 30	// ── Types ─────────────────────────────────────────────────────────────────────
 31	
 32	export interface FeatureNotificationState {
 33	  /** Features for which feature_start has been dispatched in this process run. */
 34	  startedFeatures: Set<string>;
 35	  /** Last seen compound status key per featureId: "<feature_status>|<next_action>". */
 36	  lastStatusKeys: Map<string, string>;
 37	}
 38	
 39	export function createFeatureNotificationState(): FeatureNotificationState {
 40	  return {
 41	    startedFeatures: new Set(),
 42	    lastStatusKeys: new Map(),
 43	  };
 44	}
