103	/**
104	 * Read status.yaml for a feature from origin/<featureBranch>, falling back to
105	 * origin/baseBranch then local FS. Returns null when unreadable.
106	 */
107	function readStatusYaml(
108	  workspaceRoot: string,
109	  featureId: string,
110	  env: NodeJS.ProcessEnv,
111	): StatusYaml | null {
112	  const featureBranch = featureBranchName(featureId);
113	  const relPath = statusYamlRelPath(featureId);
114	
115	  for (const ref of [`origin/${featureBranch}`, "origin/main"]) {
116	    try {
117	      const raw = execSync(
118	        `git -C "${workspaceRoot}" show "${ref}:${relPath}"`,
119	        { encoding: "utf-8", stdio: "pipe" },
120	      );
121	      const parsed = parseYaml(raw) as StatusYaml | undefined;
122	      if (parsed && typeof parsed === "object") return parsed;
123	    } catch { /* try next ref */ }
124	  }
125	
126	  const absPath = join(workspaceRoot, "docs", "features", featureId, "status.yaml");
127	  if (!existsSync(absPath)) return null;
128	  try {
129	    return parseYaml(readFileSync(absPath, "utf-8")) as StatusYaml;
130	  } catch {
131	    return null;
132	  }
133	}
