135	/**
136	 * Count task YAML files for a feature from origin/<featureBranch>.
137	 * Returns 0 when unreachable.
138	 */
139	function countTaskFiles(
140	  workspaceRoot: string,
141	  featureId: string,
142	  env: NodeJS.ProcessEnv,
143	): number {
144	  const featureBranch = featureBranchName(featureId);
145	  const tasksRelDir = join("docs", "features", featureId, TASKS_DIR);
146	  try {
147	    const listing = execSync(
148	      `git -C "${workspaceRoot}" ls-tree --name-only "origin/${featureBranch}" "${tasksRelDir}/"`,
149	      { encoding: "utf-8", stdio: "pipe" },
150	    );
151	    return listing
152	      .split("\n")
153	      .map((f) => f.trim())
154	      .filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
155	  } catch {
156	    // Feature branch may not exist yet — fall back to local FS count
157	    const dir = join(workspaceRoot, "docs", "features", featureId, TASKS_DIR);
158	    if (!existsSync(dir)) return 0;
159	    try {
160	      return readdirSync(dir).filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
161	    } catch {
162	      return 0;
163	    }
164	  }
165	}
166	
167	function buildFeatureContext(
168	  statusYaml: StatusYaml,
169	  totalTaskCount: number,
170	): FeatureContext {
171	  const history = statusYaml.history ?? [];
172	  const lastEntry = history[history.length - 1];
173	  return {
174	    title: statusYaml.title ?? "Untitled feature",
175	    status: statusYaml.feature_status ?? "unknown",
176	    nextAction: statusYaml.next_action ?? null,
177	    handoff: statusYaml.handoff_pr_url ?? null,
178	    featurePr: statusYaml.workspace_feature_pr_url ?? null,
179	    totalTaskCount,
180	    lastUpdatedAt: lastEntry?.at ?? null,
181	  };
182	}
183	
184	/** Compound status key that captures all feature-level fields we watch. */
185	function statusKey(s: StatusYaml): string {
186	  return `${s.feature_status ?? ""}|${s.next_action ?? ""}`;
187	}
188	
189	// ── Public API ────────────────────────────────────────────────────────────────
190	
191	/**
192	 * One poll cycle of feature notification detection.
193	 *
194	 * Non-throwing: errors per-feature are emitted and the scan continues.
195	 */
196	export async function runFeatureNotificationStep(
197	  opts: RunFeatureNotificationOpts,
198	): Promise<void> {
199	  const {
200	    workspaceRoot,
201	    workspaceId,
202	    notificationPort,
203	    state,
204	    gitAuthorEmail = "coder@workflow",
205	    gitAuthorName = gitAuthorEmail,
206	    sshKeyPath,
207	    emit,
208	  } = opts;
209	
210	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
211	
212	  const featureIds = listFeatureIds(workspaceRoot);
213	
214	  for (const featureId of featureIds) {
215	    try {
216	      const statusYaml = readStatusYaml(workspaceRoot, featureId, env);
217	      if (!statusYaml) continue;
218	
219	      const featureStatus = statusYaml.feature_status ?? "";
220	
221	      // Skip terminal features entirely.
222	      if (TERMINAL_STATUSES.has(featureStatus)) continue;
223	
224	      // Only watch features in known active states.
225	      if (!WATCHED_STATUSES.has(featureStatus)) continue;
226	
227	      const totalTaskCount = countTaskFiles(workspaceRoot, featureId, env);
228	      const context = buildFeatureContext(statusYaml, totalTaskCount);
229	      const currentKey = statusKey(statusYaml);
230	
231	      if (!state.startedFeatures.has(featureId)) {
232	        // First time we observe this feature as active — send feature_start.
233	        // Only do this for truly active (not in_handoff) features so that a
234	        // process restart after handoff doesn't re-trigger start.
235	        if (ACTIVE_STATUSES.has(featureStatus)) {
236	          emit({ type: "feature_notification_start", feature_id: featureId });
237	          await notificationPort.postFeatureMessage(featureId, "feature_start", context);
238	          state.startedFeatures.add(featureId);
239	          state.lastStatusKeys.set(featureId, currentKey);
240	        } else {
241	          // in_handoff and not previously started — still record as seen.
242	          state.startedFeatures.add(featureId);
243	          state.lastStatusKeys.set(featureId, currentKey);
244	        }
245	      } else {
246	        // Feature already seen — check if status changed.
247	        const lastKey = state.lastStatusKeys.get(featureId);
248	        if (lastKey !== currentKey) {
249	          emit({
250	            type: "feature_notification_summary_changed",
251	            feature_id: featureId,
252	            prev_status: lastKey ?? "",
253	            new_status: currentKey,
254	          });
255	          await notificationPort.postFeatureMessage(
256	            featureId,
257	            "feature_summary_changed",
258	            context,
259	          );
260	          state.lastStatusKeys.set(featureId, currentKey);
261	        }
262	        // No change — routine poll, no port call.
263	      }
264	    } catch (e) {
265	      emit({
266	        type: "feature_notification_watcher_error",
267	        feature_id: featureId,
268	        details: String(e),
269	      });
270	    }
271	  }
272	}

