1	/**
2	 * Feature-Tasks-Done checker — polls for features where all tasks are done
3	 * and fires the Handoff Trigger.
4	 *
5	 * Runs on every poll cycle (after handleMergedPrs). Reads task YAMLs from
6	 * origin/<featureBranch> — the authoritative multi-task view — rather than
7	 * from the local FS of a single task branch.
8	 *
9	 * A feature is eligible when:
10	 *   - feature_status is not already "in_handoff", "done", or "cancelled"
11	 *   - handoff_pr_url is null (idempotent guard)
12	 *   - every T*.yaml on origin/<featureBranch> has status "done" or "cancelled"
13	 *   - at least one task is "done" (pure-cancelled features are skipped)
14	 *
15	 * This replaces the inline checkAllTasksDone + fireHandoffTrigger calls that
16	 * previously lived inside handle-merged-prs and dispatch-review-result, both
17	 * of which read from the local task-branch FS and could fire too early when
18	 * sibling task YAMLs were not yet present on that branch.
19	 */
20	
21	import { existsSync, readdirSync, readFileSync } from "node:fs";
22	import { execSync } from "node:child_process";
23	import { join } from "node:path";
24	import { parse as parseYaml } from "yaml";
25	import type { Task } from "../types/task.js";
