    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("emits skipped and returns when no github token", async () => {
    const wsRoot = makeTmpWorkspace();

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: "",
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "check_feature_tasks_done_skipped")).toBe(true);
