/**
 * Tests for check-feature-tasks-done.ts
 *
 * The poll step reads task YAMLs from origin/<featureBranch> via git show and
 * fires the Handoff Trigger when all tasks are done/cancelled.
 *
 * Test matrix:
 *  1. All tasks done → fires handoff trigger.
 *  2. Tasks done + cancelled mix → fires handoff trigger.
 *  3. One task still in_progress → does not fire.
 *  4. Feature already in_handoff → skips.
 *  5. Feature already done → skips.
 *  6. handoff_pr_url already set → skips (idempotent).
 *  7. Only cancelled tasks (no done) → does not fire.
 *  8. No task files on feature branch → does not fire.
 *  9. git fetch fails → emits fetch_failed and returns without firing.
 * 10. No github token → emits skipped and returns.
 * 11. Multiple features — only the fully-done one fires.
 * 12. fireHandoffTrigger error → emits handoff_trigger_failed, continues.
 * 13. notificationPort provided → postFeatureMessage(handoff_submitted) called after successful handoff.
 * 14. notificationPort provided but fireHandoffTrigger errors → postFeatureMessage NOT called.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify } from "yaml";
import type { Task } from "../src/types/task.js";
import type { NotificationPort } from "../src/notifications/notification.port.js";

// ── Mocks ─────────────────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn() };
});

vi.mock("../src/handoff/handoff-trigger.js", () => ({
  fireHandoffTrigger: vi.fn(),
}));

vi.mock("../src/config/workspace-config.js", () => ({
  parseManagementRepoCoords: vi.fn(() => ({
    owner: "test-owner",
    repo: "test-repo",
    baseBranch: "main",
  })),
}));

// ── Imports after mocks ───────────────────────────────────────────────────────

import { execSync } from "node:child_process";
import { checkFeatureTasksDone } from "../src/poll/check-feature-tasks-done.js";
import { fireHandoffTrigger } from "../src/handoff/handoff-trigger.js";

const mockExecSync = vi.mocked(execSync);
const mockFireHandoffTrigger = vi.mocked(fireHandoffTrigger);

// ── Mock NotificationPort builder ─────────────────────────────────────────────

function makeMockPort(): NotificationPort & {
  postFeatureMessage: ReturnType<typeof vi.fn>;
  closeFeatureThread: ReturnType<typeof vi.fn>;
  postTaskMessage: ReturnType<typeof vi.fn>;
  closeTaskThread: ReturnType<typeof vi.fn>;
} {
  return {
    postFeatureMessage: vi.fn().mockResolvedValue(undefined),
    closeFeatureThread: vi.fn().mockResolvedValue(undefined),
    postTaskMessage: vi.fn().mockResolvedValue(undefined),
    closeTaskThread: vi.fn().mockResolvedValue(undefined),
  };
}

// ── Constants ─────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const FEATURE_BRANCH = `feature/${FEATURE_ID}`;
const GITHUB_TOKEN = "ghp_test";
const GIT_EMAIL = "bot@test.com";

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpWorkspace(): string {
  const dir = mkdtempSync(join(tmpdir(), "check-feature-tasks-done-"));
  tmpDirs.push(dir);
  mkdirSync(join(dir, "docs", "features", FEATURE_ID), { recursive: true });
  return dir;
}

function writeStatusYaml(wsRoot: string, featureId: string, status: Record<string, unknown>): void {
  writeFileSync(
    join(wsRoot, "docs", "features", featureId, "status.yaml"),
    yamlStringify(status),
    "utf-8",
  );
}

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "workflow",
    status: "done",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: { actor_type: "agent", last_updated_by: GIT_EMAIL, last_updated_at: "2026-05-13T00:00:00Z" },
    pr: { url: `https://github.com/test-owner/agent-workflow/pull/1`, status: "merged" },
    workspace_pr: null,
    log: [{ action: "done", by: GIT_EMAIL, at: "2026-05-13T00:00:00Z", note: "Done." }],
    ...overrides,
  };
}

/**
 * Configure execSync to return:
 *  - "" for git fetch (success)
 *  - ls-tree listing for the feature branch
 *  - task YAML content for each git show call
 *  - status YAML content for status.yaml reads
 */
function setupGitMocks(
  wsRoot: string,
  tasks: Task[],
  statusContent?: string,
): void {
  const tasksDir = join("docs", "features", FEATURE_ID, "tasks");
  const taskFileList = tasks.map((t) => `${tasksDir}/${t.id}.yaml`).join("\n");

  mockExecSync.mockImplementation((cmd: string) => {
    const cmdStr = String(cmd);

    if (cmdStr.includes("fetch origin")) return "";

    // Status YAML read.
    if (cmdStr.includes("status.yaml")) {
      if (statusContent) return statusContent;
      throw new Error("status.yaml not found");
    }

    // ls-tree for task file listing.
    if (cmdStr.includes("ls-tree")) return taskFileList;

    // Individual task YAML reads via git show.
    for (const task of tasks) {
      if (cmdStr.includes(`${task.id}.yaml`)) {
        return yamlStringify(task);
      }
    }

    return "";
  });
}

// ── Setup / teardown ──────────────────────────────────────────────────────────

beforeEach(() => {
  vi.clearAllMocks();
  mockFireHandoffTrigger.mockResolvedValue({ prUrl: "https://github.com/test-owner/test-repo/pull/99" });
});

afterEach(() => {
  for (const dir of tmpDirs.splice(0)) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
  }
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("checkFeatureTasksDone", () => {
  it("fires handoff trigger when all tasks are done", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1"), makeTask("T2")];
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    setupGitMocks(wsRoot, tasks, status);

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "all_tasks_done")).toBe(true);
    expect(mockFireHandoffTrigger).toHaveBeenCalledOnce();
    expect(mockFireHandoffTrigger).toHaveBeenCalledWith(
      expect.objectContaining({ featureId: FEATURE_ID }),
    );
  });

  it("fires when some tasks are cancelled and at least one is done", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1"), makeTask("T2", { status: "cancelled" })];
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    setupGitMocks(wsRoot, tasks, status);

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "all_tasks_done")).toBe(true);
    expect(mockFireHandoffTrigger).toHaveBeenCalledOnce();
  });

  it("does not fire when a task is still in_progress", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1"), makeTask("T2", { status: "in_progress" })];
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    setupGitMocks(wsRoot, tasks, status);

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "all_tasks_done")).toBe(false);
    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("skips features already in_handoff", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1"), makeTask("T2")];
    const status = yamlStringify({ feature_status: "in_handoff", handoff_pr_url: "https://github.com/x/y/pull/1" });
    setupGitMocks(wsRoot, tasks, status);

    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: vi.fn(),
    });

    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("skips features already done", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1")];
    const status = yamlStringify({ feature_status: "done", handoff_pr_url: "https://github.com/x/y/pull/1" });
    setupGitMocks(wsRoot, tasks, status);

    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: vi.fn(),
    });

    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("skips when handoff_pr_url already set (idempotent)", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1")];
    const status = yamlStringify({
      feature_status: "in_implementation",
      handoff_pr_url: "https://github.com/x/y/pull/99",
    });
    setupGitMocks(wsRoot, tasks, status);

    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: vi.fn(),
    });

    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("does not fire when all tasks are cancelled and none done", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1", { status: "cancelled" }), makeTask("T2", { status: "cancelled" })];
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    setupGitMocks(wsRoot, tasks, status);

    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: vi.fn(),
    });

    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("does not fire when no task files exist on feature branch", async () => {
    const wsRoot = makeTmpWorkspace();
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });

    mockExecSync.mockImplementation((cmd: string) => {
      const cmdStr = String(cmd);
      if (cmdStr.includes("fetch origin")) return "";
      if (cmdStr.includes("status.yaml")) return status;
      if (cmdStr.includes("ls-tree")) return ""; // empty listing
      return "";
    });

    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: vi.fn(),
    });

    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("emits fetch_failed and returns without firing when git fetch fails", async () => {
    const wsRoot = makeTmpWorkspace();

    mockExecSync.mockImplementation((cmd: string) => {
      if (String(cmd).includes("fetch origin")) throw new Error("network error");
      return "";
    });

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "check_feature_tasks_done_fetch_failed")).toBe(true);
    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("emits skipped and returns when no github token", async () => {
    const wsRoot = makeTmpWorkspace();

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: "",
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "check_feature_tasks_done_skipped")).toBe(true);
    expect(mockExecSync).not.toHaveBeenCalled();
    expect(mockFireHandoffTrigger).not.toHaveBeenCalled();
  });

  it("only fires for the fully-done feature among multiple features", async () => {
    const wsRoot = mkdtempSync(join(tmpdir(), "check-feature-tasks-done-multi-"));
    tmpDirs.push(wsRoot);

    const doneFeature = "done-feature";
    const pendingFeature = "pending-feature";
    mkdirSync(join(wsRoot, "docs", "features", doneFeature), { recursive: true });
    mkdirSync(join(wsRoot, "docs", "features", pendingFeature), { recursive: true });

    const doneTask = makeTask("T1");
    const pendingTask = makeTask("T1", { status: "in_progress" });

    const doneStatus = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    const pendingStatus = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });

    mockExecSync.mockImplementation((cmd: string) => {
      const cmdStr = String(cmd);
      if (cmdStr.includes("fetch origin")) return "";

      if (cmdStr.includes(`features/${doneFeature}/status.yaml`)) return doneStatus;
      if (cmdStr.includes(`features/${pendingFeature}/status.yaml`)) return pendingStatus;

      if (cmdStr.includes(`features/${doneFeature}`) && cmdStr.includes("ls-tree")) {
        return `docs/features/${doneFeature}/tasks/T1.yaml`;
      }
      if (cmdStr.includes(`features/${pendingFeature}`) && cmdStr.includes("ls-tree")) {
        return `docs/features/${pendingFeature}/tasks/T1.yaml`;
      }

      if (cmdStr.includes(`features/${doneFeature}`) && cmdStr.includes("T1.yaml")) {
        return yamlStringify(doneTask);
      }
      if (cmdStr.includes(`features/${pendingFeature}`) && cmdStr.includes("T1.yaml")) {
        return yamlStringify(pendingTask);
      }

      return "";
    });

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(mockFireHandoffTrigger).toHaveBeenCalledOnce();
    expect(mockFireHandoffTrigger).toHaveBeenCalledWith(
      expect.objectContaining({ featureId: doneFeature }),
    );
    const allTasksDoneEvents = events.filter((e) => e["type"] === "all_tasks_done");
    expect(allTasksDoneEvents).toHaveLength(1);
    expect(allTasksDoneEvents[0]!["feature_id"]).toBe(doneFeature);
  });

  it("emits handoff_trigger_failed and continues when fireHandoffTrigger returns error", async () => {
    const wsRoot = makeTmpWorkspace();
    const tasks = [makeTask("T1")];
    const status = yamlStringify({ feature_status: "in_implementation", handoff_pr_url: null });
    setupGitMocks(wsRoot, tasks, status);

    mockFireHandoffTrigger.mockResolvedValue({ error: "push failed" });

    const events: Record<string, unknown>[] = [];
    await checkFeatureTasksDone({
      workspaceRoot: wsRoot,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "handoff_trigger_failed")).toBe(true);
  });
});

